    add_structural_heading(doc, "ВСТУП", page_break=True)
    add_body_p(doc, "Актуальність теми. Стрімкий розвиток сервісної економіки та спільного користування матеріально-технічними ресурсами зумовлює високий попит на автоматизовані вебсистеми прокату спеціалізованого обладнання — від резервних джерел живлення й професійної фото- та відеотехніки до будівельного інструменту й високоточних геодезичних і тепловізійних приладів. На відміну від типових інтернет-магазинів, де товар списується зі складу назавжди за кількісним залишком, облік оренди оперує конкретними фізичними екземплярами з індивідуальними інвентарними номерами у просторі та часі. Головною інженерною проблемою таких систем є уникнення колізій розкладу (подвійного бронювання однієї фізичної одиниці на перетинні інтервали), обов’язкове резервування технологічного часу на огляд, чищення й підзаряджання приладу після кожного повернення (технічної перерви), а також точний фінансовий розрахунок вартості оренди, поворотної застави та штрафних санкцій за прострочення без похибок рухомої коми.")
    add_body_p(doc, "Ведення прокатного журналу в електронних таблицях або універсальних облікових програмах призводить до частих операційних помилок: менеджер може підтвердити заявку без урахування часу на сервісне обслуговування між двома клієнтами, пропустити звільнення слота для клієнтів із листа очікування або допустити розбіжності при перерахунку погодинної та подобової тарифікації. Тому розроблення спеціалізованої клієнт-серверної вебсистеми з наочним поекземплярним календарем доступності, серверним контролем предметних інваріантів і транзакційним захистом даних є актуальним науково-практичним завданням у межах підготовки фахівців спеціальності 122 «Комп’ютерні науки».")
    add_body_p(doc, "Мета курсової роботи — спроєктувати, програмно реалізувати та експериментально дослідити клієнт-серверну вебсистему оренди обладнання з календарем доступності (Варіант 12), яка забезпечує поекземплярний облік інвентарних одиниць, атомарне виключення накладань орендних інтервалів з урахуванням технічної перерви між видачами, точний цілочисельний розрахунок вартості й пені за прострочення, а також автоматизоване ведення черги очікування.")
    add_body_p(doc, "Для досягнення поставленої мети у роботі сформульовано та розв’язано такі основні завдання:")
    add_bullet_p(doc, "провести аналіз предметної області ", "прокату обладнання, виконати порівняльний огляд існуючих аналогів, визначити межі системи та розмежувати права доступу ролей Гість, Клієнт і Менеджер прокату;")
    add_bullet_p(doc, "сформулювати перевірювані вимоги ", "до функціональності (FR-01..FR-09) і нефункціональних характеристик якості (NFR-01..NFR-08) та побудувати модель прецедентів UML Use Case;")
    add_bullet_p(doc, "формалізувати алгоритмічне забезпечення ", "перевірки перетину напіввідкритих часових інтервалів із буфером технічного обслуговування, розрахунку вартості й пені у копійках та атомарного створення бронювання;")
    add_bullet_p(doc, "виконати багатопоглядове проєктування ", "вебсистеми за 12 архітектурними поданнями, включаючи проєктування UI, логічної та фізичної схем реляційної бази даних SQLite, контрактів REST API за RFC 9457 та моделі безпеки за OWASP Top 10:2025 і ASVS 5.0.0;")
    add_bullet_p(doc, "реалізувати серверну частину ", "на базі C# / ASP.NET Core 10.0 Web API з пошаровою архітектурою (Domain, Application, Infrastructure, WebApi) та клієнтський застосунок на React 19;")
